function recordIdKey(id) {
  if (typeof id === 'number') return `n:${id}`;
  return `s:${id}`;
}

export function mergeRecords(records, incoming) {
  const indexByKey = new Map();
  for (let i = 0; i < records.length; i++) {
    indexByKey.set(recordIdKey(records[i].id), i);
  }
  for (const record of incoming) {
    const key = recordIdKey(record.id);
    const index = indexByKey.get(key);
    if (index === undefined) {
      indexByKey.set(key, records.length);
      records.push(record);
    } else {
      records[index] = record;
    }
  }
  return records;
}

